// 从已冻结只读检查器提取的原生读回；不导航、不写锁、不改手机。
import fs from 'node:fs';import os from 'node:os';import path from 'node:path';import {spawn} from 'node:child_process';
import {fileURLToPath} from 'node:url';
import {localEnvironment} from './local-transport.mjs';
function sshRead(command,args,input) {
  return new Promise((resolve,reject)=>{
    const child=spawn(command,args,{stdio:['pipe','pipe','pipe']});let output='';
    const timer=setTimeout(()=>{child.kill('SIGTERM');reject(Error('SSH_READ_TIMEOUT'));},35000);
    child.stdout.on('data',b=>{output+=b;if(output.length>1024*1024)child.kill('SIGTERM');});
    child.stderr.on('data',()=>{});child.stdin.on('error',()=>{});
    child.once('error',e=>{clearTimeout(timer);reject(e);});
    child.once('close',rc=>{clearTimeout(timer);rc===0?resolve(output):reject(Error('SSH_READ_UNAVAILABLE'));});child.stdin.end(input);
  });
}

export function evaluateNative(facts,c,activity) {
  const pre=facts.preflight, lock=facts.local_lock, central=facts.central;
  const output={};const put=(key,value,observation)=>{output[key]={value,observation};};
  if(activity==='preflight') {
    put('device_online',pre?pre.state==='device'&&pre.profile===c.profile&&(c.transport==='local'?pre.serial===c.adb_serial&&pre.hardware_serial===c.serial:pre.serial===c.serial):null,{preflight:pre||'unavailable'});
    put('call_idle',pre&&['idle','offhook','ringing'].includes(pre.call_state)?pre.call_state==='idle':null,{call_state:pre?.call_state||'unknown'});
    const fresh=facts.account&&Number.isFinite(facts.account.age_s)&&facts.account.age_s>=0&&facts.account.age_s<=120;
    put('native_account_identity',fresh?facts.account.account===c.account:null,{account_evidence:facts.account||'unavailable',fresh:!!fresh});
    const localOwned=lock?.lock==='held'&&lock.owner===c.local_owner&&lock.stale==='false'&&lock.reclaimable==='false';
    const centralOwned=central?.locked_by===c.central_owner&&Date.parse(central.expires_at)>Date.now();
    put('resource_ownership',!lock||!central?null:localOwned&&centralOwned,{local_lock:lock||'unavailable',central_lock:central||'unavailable'});
    put('cleanup_responsibility',c.verification.native?.cleanup_owner===c.tasks[c.assigned_workflow].task_id,{cleanup_owner:c.verification.native?.cleanup_owner||'unknown'});
  } else {
    put('local_lock_released',lock?lock.lock==='free':null,{local_lock:lock||'unavailable'});
    put('central_lock_released',central?central.locked_by===null:null,{central_lock:central||'unavailable'});
    const home=c.verification.native?.home_package;
    put('safe_desktop',pre&&home?pre.foreground_package===home:null,{expected_home:home||'unknown',actual:pre?.foreground_package||'unknown'});
    put('native_operations_terminal',facts.operations?facts.operations.live_pids.length===0&&facts.operations.native_process_count===0:null,{operations:facts.operations||'unavailable'});
  }
  return output;
}
export async function readNative(c,run) {
  const facts={};
  try {
    const cache=fs.readFileSync(path.join(os.homedir(),'.credentials/cecelia-internal.env'),'utf8');
    const line=cache.split('\n').find(l=>/^(BRAIN_INTERNAL_TOKEN|CECELIA_INTERNAL_TOKEN)=/.test(l));
    const raw=line.slice(line.indexOf('=')+1);let token;try{token=JSON.parse(raw);}catch{token=raw.replace(/^['"]|['"]$/g,'');}
    const r=await fetch('http://127.0.0.1:5221/api/brain/device-locks',{headers:{'X-Internal-Token':token},signal:AbortSignal.timeout(5000)});
    if(!r.ok)throw Error('CENTRAL_UNAVAILABLE');
    const b=await r.json(), rows=b.locks?.filter(x=>x.device_name===c.serial);
    if(rows?.length===1)facts.central={locked_by:rows[0].locked_by,expires_at:rows[0].expires_at,lease_version:rows[0].lease_version};
  }catch{}
  if(c.transport==='local'){
    try{
      localEnvironment(c);
      const raw=await sshRead(c.python??'/opt/homebrew/bin/python3',[path.join(path.dirname(fileURLToPath(import.meta.url)),'native-probe.py')],JSON.stringify({...c,run}));
      Object.assign(facts,JSON.parse(raw));
    }catch{}
    return facts;
  }
  const n=c.verification.native;
  if(!n||!['xian-m4','xian-m4-cf','xian-m1'].includes(n.ssh_host)||c.profile!=='xiaolongxia'||c.serial!=='ANGYVB4311010223')return facts;
  if(n.ssh_jump&&n.ssh_jump!=='xian-m1')return facts;
  const payload=Buffer.from(JSON.stringify({profile:c.profile,serial:c.serial,run,account:c.account})).toString('base64');
  // Fixed read-only CLI methods; no account navigation, lock mutation, stop/kill, or bare ADB.
  const code=`import subprocess,json,pathlib,os,re,time,base64,xml.etree.ElementTree as E
c=json.loads(base64.b64decode('${payload}')); out={}
cli=str(pathlib.Path.home()/'.local/bin/douyin-phone-adb')
for cmd,name in [('preflight','preflight'),('lock-status','local_lock')]:
 try:
  r=subprocess.run([cli,'--profile',c['profile'],cmd],capture_output=True,text=True,timeout=12)
  if r.returncode==0:
   if cmd=='preflight':
    fields=dict(l.split('=',1) for l in r.stdout.splitlines() if '=' in l)
    m=re.search(r'([A-Za-z][A-Za-z0-9_.]+)/',fields.get('foreground',''));fields['foreground_package']=m.group(1) if m else None
   else:fields=dict(re.findall(r'(\\w+)=([^\\s]+)',r.stdout))
   out[name]=fields
  elif cmd=='preflight' and 'target phone is offline' in r.stderr:
   out[name]={'state':'offline','serial':c['serial'],'profile':c['profile'],'call_state':'unknown'}
 except:pass
root=pathlib.Path('/private/tmp/openclaw-phone/evidence')/c['profile']
try:
 files=sorted(root.glob(c['run']+'*-profile.xml'),key=lambda p:p.stat().st_mtime,reverse=True)
 if files:
  p=files[0];raw=p.read_bytes();tree=E.fromstring(raw)
  values=[a for node in tree.iter('node') for a in [node.get('text',''),node.get('content-desc','')]]
  ids=set()
  for text in values:
   m=re.fullmatch(r'(?:抖音号[:：]\\s*)([A-Za-z0-9_.-]+)',text.strip())
   if m:ids.add(m.group(1))
  out['account']={'account':next(iter(ids)) if len(ids)==1 else None,'age_s':time.time()-p.stat().st_mtime,'source':p.name,'sha256':__import__('hashlib').sha256(raw).hexdigest()}
except:pass
try:
 live=[]
 for p in root.glob(c['run']+'*.rec.pid'):
  pid=int(p.read_text().strip())
  try:os.kill(pid,0);live.append(pid)
  except ProcessLookupError:pass
  except:live.append(pid)
 ps=subprocess.check_output(['/bin/ps','-axo','pid,command'],text=True)
 count=sum(1 for line in ps.splitlines() if c['profile'] in line and 'douyin-phone-adb' in line)
 out['operations']={'live_pids':live,'native_process_count':count}
except:pass
print(json.dumps(out))
`;
  try {
    const r=await sshRead('ssh',['-o','BatchMode=yes','-o','ControlMaster=no','-o','ControlPath=none','-o','ConnectTimeout=6',...(n.ssh_jump?['-J',n.ssh_jump]:[]),n.ssh_host,'python3 -'],code);
    Object.assign(facts,JSON.parse(r));
  }catch{}
  return facts;
