import {evaluateNative,readNative} from './native-readback.mjs';
export {evaluateNative};
// Pure readback only: no queue writes, no model evaluation, no phone navigation.
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import crypto from 'node:crypto';
import {createRequire} from 'node:module';
import {isDeepStrictEqual} from 'node:util';
import {spawn} from 'node:child_process';
function sshRead(command,args,input) {
  return new Promise((resolve,reject)=>{
    const child=spawn(command,args,{stdio:['pipe','pipe','pipe']});let output='';
    const timer=setTimeout(()=>{child.kill('SIGTERM');reject(Error('SSH_READ_TIMEOUT'));},35000);
    child.stdout.on('data',b=>{output+=b;if(output.length>1024*1024)child.kill('SIGTERM');});
    child.stderr.on('data',()=>{});child.stdin.on('error',()=>{});
    child.once('error',e=>{clearTimeout(timer);reject(e);});
    child.once('close',rc=>{clearTimeout(timer);rc===0?resolve(output):reject(Error('SSH_READ_UNAVAILABLE'));});child.stdin.end(input);
  });
}

const hash = bytes => crypto.createHash('sha256').update(bytes).digest('hex');
const UUID=/^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/i;
const VID=/^\d{16,24}$/;
export function exactIds(ids, pattern, cap=50) {
  if (!Array.isArray(ids)||!ids.length||ids.length>cap||new Set(ids).size!==ids.length||ids.some(id=>typeof id!=='string'||!pattern.test(id))) throw Error('EXACT_INPUT_SCOPE_REQUIRED');
  return ids;
}
export function runOutputIds(rows,run,cap) {
  if(!Number.isInteger(cap)||cap<1||cap>100)throw Error('RUN_OUTPUT_LIMIT_REQUIRED');
  if(rows.some(r=>r.discovery_metrics?.run!==run))throw Error('FOREIGN_RUN_OUTPUT');
  return exactIds(rows.map(r=>r.video_id),VID,cap);
}
export function collectedOutputIds(rows,run,videoIds,cap) {
  exactIds(videoIds,VID,1000);
  if(!Number.isInteger(cap)||cap<1||cap>50)throw Error('COMMENT_OUTPUT_LIMIT_REQUIRED');
  if(rows.some(r=>r.harvest_batch!==run||!videoIds.some(id=>r.source_video_url==='https://www.douyin.com/video/'+id)))throw Error('FOREIGN_COLLECTION_OUTPUT');
  return exactIds(rows.map(r=>r.id),UUID,cap);
}
export function verifiedEmptyQueue(pending, scoresWritten, auditEntries) {
  return Array.isArray(pending)&&pending.length===0&&Number.isInteger(scoresWritten)&&scoresWritten===0
    &&Array.isArray(auditEntries)&&auditEntries.length===0;
}
export function frozenMatches(row,c,run) {
  const s=row?.snapshot;
  const accounts=s?.runtime_config?.platform_accounts?.filter(a=>a.profile===c.profile&&a.enabled!==false)||[];
  const binding=accounts.length===1&&accounts[0].enabled===true&&accounts[0].verification_status==='verified'
    &&accounts[0].device_serial===c.serial&&accounts[0].douyin_id===c.account;
  return Boolean(binding&&row&&s&&row.run_id===run&&row.company_id===c.company_id&&row.tenant_id===c.tenant_id
    &&s.company_id===row.company_id&&s.tenant_id===row.tenant_id&&Number(row.version)===Number(s.version)
    &&Number(row.version)===c.verification.policy_version&&s.policy_id===c.verification.policy_id
    &&s.config_status==='enabled'&&s.runtime_config?.routing?.line_key===c.line);
}
export function semanticMetricsMatch(stored,rebuilt,scope) {
  return Object.entries(scope).every(([key,value])=>stored[key]===value)&&isDeepStrictEqual(stored,rebuilt);
}
export function resolveOutcomes(videos) {
  return videos.length>0&&videos.every(v=>['matched','rejected'].includes(v.judgment_status));
}
export function qualificationMatchesPolicy(row,c) {
  const policy=row?.judgment_config,expected=c.verification;
  return Boolean(policy&&policy.company_id===c.company_id&&policy.tenant_id===c.tenant_id
    &&Number(policy.version)===expected.policy_version&&policy.policy_id===expected.policy_id);
}
export function eligibleForQualification(row,c) {
  return ['pending','matched','rejected'].includes(row?.judgment_status)
    &&(row.judgment_status!=='rejected'||!qualificationMatchesPolicy(row,c));
}
async function brainRead(endpoint) {
  const cache=fs.readFileSync(path.join(os.homedir(),'.credentials/cecelia-internal.env'),'utf8');
  const line=cache.split('\n').find(l=>/^(BRAIN_INTERNAL_TOKEN|CECELIA_INTERNAL_TOKEN)=/.test(l));
  const raw=line.slice(line.indexOf('=')+1);let token;try{token=JSON.parse(raw);}catch{token=raw.replace(/^['"]|['"]$/g,'');}
  const r=await fetch('http://127.0.0.1:5221/api/brain'+endpoint,{headers:{'X-Internal-Token':token},signal:AbortSignal.timeout(5000)});
  if(!r.ok)throw Error('BRAIN_READ_UNAVAILABLE');return r.json();
}
export function downstreamDeliveryMatch(row,record,task,c,txt) {
  let result=task?.result;if(typeof result==='string')try{result=JSON.parse(result);}catch{return false;}
  const b=result?.business_result, fields=record?.fields;
  if(!row.fields||!Object.hasOwn(row.fields,'抖音号')||!Object.hasOwn(row.fields,'合规核验状态')
    ||task?.status!=='completed'||!b?.writeback_verified||b.record_id!==row.feishu_record_id||record.record_id!==row.feishu_record_id
    ||b.recipient!==row.payload.target_douyin_id||b.sender!==c.account||!b.message||!/^[A-Za-z0-9][A-Za-z0-9_-]{0,119}$/.test(result.run_tag||'')
    ||!['已触达','触达受阻'].includes(b.state)||!['已发送','发送失败'].includes(b.send_status)
    ||txt(fields?.['状态'])!==b.state||txt(fields?.['发送状态'])!==b.send_status
    ||txt(fields?.['实际分发号'])!==c.profile+'('+c.account+')')return false;
  const outcome=b.state==='已触达'?'sent':null;
  if(!outcome||b.send_status!=='已发送')return false;
  const marker=txt(fields['回复结果']);
  if(!new RegExp('^\\[104 sent:'+result.run_tag+':[a-f0-9]{40}\\] '+hash(b.message)+' 送达未证$').test(marker))return false;
  return Object.entries(row.fields||{}).every(([k,value])=>['状态','发送状态'].includes(k)||txt(fields[k])===String(value));
}
async function artifactCheck(v,kind,spec) {
  const program=v.artifact_checker;
  if(!program||!Array.isArray(program.command)||program.command.length!==2)throw Error('ARTIFACT_CHECKER_UNBOUND');
  for(const file of program.command)if(!path.isAbsolute(file)||hash(fs.readFileSync(file))!==program.sha256?.[file])throw Error('ARTIFACT_CHECKER_SOURCE_CHANGED');
  return JSON.parse(await sshRead(program.command[0],[program.command[1]],JSON.stringify({kind,spec})));
}
function evidenceFor(v,stage,identity) {
  const own=v[stage]||{};
  if(!v.proof_manifest_path)return own;
  const filename=path.resolve(v.proof_manifest_path);
  if(!path.isAbsolute(v.proof_manifest_path)||filename.startsWith(process.cwd()+'/'))throw Error('HOST_PROOF_MANIFEST_REQUIRED');
  const manifest=JSON.parse(fs.readFileSync(filename));
  if(manifest.schema!=='activity-evidence/v1'||!['task_id','run_id','run_tag','workflow'].every(k=>manifest.identity?.[k]===identity[k]))throw Error('PROOF_MANIFEST_SCOPE_MISMATCH');
  // Tool host can publish new raw proof references; cannot replace frozen input scope or policy.
  return {...own,filter_evidence:manifest.filter_evidence||own.filter_evidence,
          qualification_evidence:manifest.qualification_evidence||own.qualification_evidence};
}
export async function main(request) {
  const c=request.context, stage=request.workflow, activity=request.activity;
  const identity=Object.fromEntries(['task_id','run_id','run_tag','workflow','activity','attempt'].map(k=>[k,request[k]]));
  const checks=new Map(request.checks.map(id=>[id,{id,status:'unknown',evidence:[{source:'production-readback',observation:{reason:'not_yet_verified'}}]}]));
  const result={identity,nonce:request.nonce,checks:[],outcome:'blocked',output:{model_call_count:0,read_only:true}};
  const set=(id,passed,source,observation)=>{if(checks.has(id))checks.set(id,{id,status:passed===true?'passed':passed===false?'failed':'unknown',evidence:[{source,observation}]});};
  let pool,client;
  try {
    if(!c||!c.verification||c.assigned_workflow!==stage||Object.keys(c.tasks).join()!==stage
      ||!['task_id','run_id','run_tag'].every(k=>c.tasks[stage][k]===request[k]))throw Error('REQUEST_SCOPE_MISMATCH');
    const v=c.verification, root=path.resolve(c.runtime_root);
    // The host pins helper implementation as well as this verifier. Never load Agent-provided code.
    if(!v.runtime_sha256||Object.keys(v.runtime_sha256).length<1)throw Error('RUNTIME_SOURCE_PINS_REQUIRED');
    for(const [relative,sha] of Object.entries(v.runtime_sha256)) {
      const full=path.resolve(root,relative);
      if(!full.startsWith(root+'/')||hash(fs.readFileSync(full))!==sha)throw Error('RUNTIME_SOURCE_CHANGED');
    }
    for(const required of ['leadgen-db-connect.js','discovery-metrics.js','leadgen-committed-partial.js','leadgen-policy-review.js','leadgen-outreach-bridge.js'])
      if(!v.runtime_sha256[required])throw Error('RUNTIME_SOURCE_PIN_MISSING');
    const require=createRequire(root+'/package.json');
    const {Pool}=require('pg');
    const privateDB=JSON.parse(fs.readFileSync(path.join(os.homedir(),'.credentials/zenithjoy-db.json'),'utf8'));
    pool=new Pool({connectionString:privateDB.DATABASE_URL,connectionTimeoutMillis:10000,max:1});
    client=await pool.connect();
    await client.query('BEGIN READ ONLY');
    await client.query("SET LOCAL statement_timeout='15000ms'");
    const db=(await client.query("select current_database() as database,current_setting('transaction_read_only') as read_only")).rows[0];
    if(db.database!=='zenithjoy'||db.read_only!=='on')throw Error('READ_ONLY_DATABASE_IDENTITY_MISMATCH');
    const query=async(sql,args)=>(await client.query(sql,args)).rows;
    const run=request.run_tag;
    const snapshots=await query('SELECT company_id,tenant_id,version,run_id,source_run,snapshot FROM zenithjoy.company_config_runs WHERE run_id=$1',[run]);
    const config=snapshots[0], configOk=snapshots.length===1&&frozenMatches(config,c,run);
    const configProof={run,company_id:config?.company_id,tenant_id:config?.tenant_id,version:config?.version,policy_id:config?.snapshot?.policy_id,exact_match:configOk};
    const source='postgres:zenithjoy/';
    set('company_policy_scope',configOk,source+'company_config_runs',configProof);
    set('company_policy_identity',configOk,source+'company_config_runs',configProof);
    set('company_scoring_policy',configOk,source+'company_config_runs',configProof);
    if(!configOk)throw Error('FROZEN_COMPANY_POLICY_MISMATCH');
    const scope=evidenceFor(v,stage,identity);
    if(['preflight','cleanup'].includes(activity)) {
      const facts=await readNative(c,run);
      for(const [id,check] of Object.entries(evaluateNative(facts,c,activity)))set(id,check.value,'native+brain:read-only',check.observation);
      if(activity==='preflight')set('company_account_binding',configOk,source+'company_config_runs',configProof);
      else {const owned=await query('SELECT video_id FROM zenithjoy.leadgen_videos WHERE line_key=$1 AND process_status=$2',[c.line,'处理中:'+run]);set('video_leases_released',owned.length===0,source+'leadgen_videos',{owned_video_ids:owned.map(x=>x.video_id)});}
    }
    if(activity==='collect_videos'||activity==='dedup'||activity==='qualification') {
      let ids;
      if(activity==='collect_videos'&&scope.output_scope==='persisted_run') {
        const produced=await query("SELECT video_id,discovery_metrics FROM zenithjoy.leadgen_videos WHERE line_key=$1 AND discovery_metrics->>'run'=$2",[c.line,run]);
        ids=runOutputIds(produced,run,scope.output_limit);
      } else ids=exactIds(scope.video_ids,VID,1000);
      const videos=await query('SELECT * FROM zenithjoy.leadgen_videos WHERE line_key=$1 AND video_id=ANY($2::text[])',[c.line,ids]);
      const exact=videos.length===ids.length&&ids.every(id=>videos.filter(r=>r.video_id===id).length===1);
      const summary={requested:ids,found:videos.map(x=>({video_id:x.video_id,status:x.judgment_status,process_status:x.process_status}))};
      result.output.video_ids=videos.map(x=>x.video_id);
      set('exact_output_scope',exact,source+'leadgen_videos',summary);
      if(activity==='collect_videos'||activity==='dedup') {
        let metricsValid=exact;const proofs=[];
        for(const row of videos) {
          try {
            const m={...row.discovery_metrics};const binding=m.company_binding;delete m.company_binding;
            if(!binding||binding.company_id!==c.company_id||binding.tenant_id!==c.tenant_id||Number(binding.version)!==v.policy_version)throw Error('METRICS_COMPANY_MISMATCH');
            const producer=activity==='collect_videos'?{run,run_id:request.run_id}:scope.upstream?.[row.video_id];
            if(!producer)throw Error('UPSTREAM_PROVENANCE_REQUIRED');
            const expected={run:producer.run,run_id:producer.run_id,profile:c.profile,source_commit:c.source_commit,line_key:c.line,video_id:row.video_id,video_url:row.video_url};
            const observed=require('./discovery-metrics.js').buildObservation({...m,xml:m.evidence?.xml});
            // JSONB reorders object keys: compare the rebuilt native proof semantically, including digest.
            if(!semanticMetricsMatch(m,observed,expected))throw Error('METRICS_REBUILD_MISMATCH');
            if(binding.run_id!==producer.run)throw Error('METRICS_PRODUCER_MISMATCH');
            proofs.push({video_id:row.video_id,digest:observed.digest,run:observed.run,likes:observed.likes.value,comment_total:observed.comment_total.value});
          } catch(error) {metricsValid=false;proofs.push({video_id:row.video_id,reason:/^[A-Z_]+$/.test(error.message)?error.message:'metrics_or_producer_unverified'});}
        }
        set('video_identity',metricsValid,source+'leadgen_videos.discovery_metrics', {proofs});
        set('same_video_metrics',metricsValid,source+'leadgen_videos.discovery_metrics',{proofs});
        set('persisted_sources',metricsValid,source+'leadgen_videos.discovery_metrics',{proofs});
        set('upstream_provenance',metricsValid,source+'leadgen_videos.discovery_metrics',{proofs});
        set('eligible_video_set',exact&&videos.every(x=>eligibleForQualification(x,c)),source+'leadgen_videos',summary);
        set('video_claim_ownership',exact&&videos.every(x=>x.process_status==='处理中:'+run),source+'leadgen_videos',summary);
        if(activity==='collect_videos'&&scope.filter_evidence) {
          const spec=scope.filter_evidence;
          if(spec.origin_run!==run)throw Error('FILTER_SOURCE_RUN_MISMATCH');
          const proof=await artifactCheck(v,'filters',spec);
          set('native_search_filters',proof.native_search_filters==='passed'?true:null,'native:replayed-filter-originals',proof);
        }
        // Missing original images are never inferred from persisted metrics.
      }
      if(activity==='qualification') {
        const policyMatch=x=>qualificationMatchesPolicy(x,c);
        set('persisted_qualification',exact&&videos.every(x=>policyMatch(x)&&['matched','rejected'].includes(x.judgment_status)),source+'leadgen_videos',summary);
        set('all_target_videos_resolved',exact&&resolveOutcomes(videos),source+'leadgen_videos',summary);
        const proofs=[];
        for(const row of videos) {
          const spec=scope.qualification_evidence?.[row.video_id];
          if(!spec){proofs.push({video_id:row.video_id,reason:'originals_missing'});continue;}
          const expectedOrigin=spec.cached===true?row.judgment_config?.run_id:run;
          if(spec.video_id!==row.video_id||spec.serial!==c.serial||spec.expected_run!==expectedOrigin)throw Error('QUALIFICATION_ARTIFACT_SCOPE_MISMATCH');
          proofs.push({video_id:row.video_id,...await artifactCheck(v,'recording',spec)});
        }
        for(const key of ['capture_or_valid_cache','asr_error_classification','native_video_identity'])
          set(key,exact&&proofs.every(p=>p[key]==='passed')?true:null,'native:recording-and-asr-originals',{proofs});
        // Resolved DB labels cannot turn a technical ASR failure or no_speech into a fresh qualification.
        if(proofs.some(p=>p.asr_classification!=='transcribed'))
          set('persisted_qualification',false,source+'leadgen_videos',{...summary,reason:'effective_transcript_unverified'});

        result.output.no_collectable_videos=exact&&videos.every(x=>x.judgment_status==='rejected');
        result.output.unresolved_video_ids=videos.filter(x=>!['matched','rejected'].includes(x.judgment_status)).map(x=>x.video_id);
      }
    }
    const emptyQueueMode=activity==='scoring'&&scope.input_mode==='empty_queue_check';
    if(emptyQueueMode) {
      if(!Array.isArray(scope.comment_ids)||scope.comment_ids.length!==0||Object.keys(scope.sources||{}).length)throw Error('EMPTY_QUEUE_SCOPE_REQUIRED');
      const pending=await query("SELECT id FROM zenithjoy.leadgen_comments WHERE line_key=$1 AND process_status='待分拣' LIMIT 1",[c.line]);
      const written=await query("SELECT count(*)::int AS count FROM zenithjoy.leadgen_comments WHERE line_key=$1 AND judgment_config->>'run_id'=$2",[c.line,run]);
      const auditDir=path.join(process.cwd(),'model-score-audit');
      const audit=fs.existsSync(auditDir)?fs.readdirSync(auditDir):[];
      const empty=verifiedEmptyQueue(pending,Number(written[0].count),audit);
      for(const id of ['committed_input_scope','qualification_and_identity','persisted_scores','no_duplicate_evaluation'])
        set(id,empty,source+'leadgen_comments/ready-queue',{line:c.line,predicate:'process_status=待分拣',pending_found:pending.map(x=>x.id),scores_written_by_this_run:Number(written[0].count),scoring_audit_entries:audit,not_applicable_when_empty:empty});
      result.output.queue_empty=empty;result.output.comment_ids=[];result.output.new_scoring_calls=empty?0:null;
    }
    if(['collection','scoring','mark_leads'].includes(activity)&&!emptyQueueMode) {
      let ids,sources=scope.sources;
      if(activity==='collection'&&scope.collection_scope==='persisted_run') {
        const produced=await query('SELECT id,source_video_url,harvest_batch FROM zenithjoy.leadgen_comments WHERE line_key=$1 AND harvest_batch=$2',[c.line,run]);
        ids=collectedOutputIds(produced,run,scope.video_ids,c.comment_limit);
        sources=Object.fromEntries(ids.map(id=>[id,run]));
      } else ids=exactIds(scope.comment_ids,UUID);
      const rows=await query('SELECT * FROM zenithjoy.leadgen_comments WHERE line_key=$1 AND id=ANY($2::uuid[])',[c.line,ids]);
      const exact=rows.length===ids.length&&ids.every(id=>rows.filter(r=>r.id===id).length===1)
        &&rows.every(r=>sources?.[r.id]===r.harvest_batch);
      const summary={requested:ids,found:rows.map(r=>({id:r.id,source_run:r.harvest_batch,status:r.process_status}))};
      set('committed_input_scope',exact,source+'leadgen_comments',summary);
      set('source_mapping',exact,source+'leadgen_comments',summary);
      let admitted=false;
      if(exact)try{const actual=await require('./leadgen-committed-partial.js').admittedRows(client,{lineKey:c.line,run,ids});admitted=actual.length===ids.length;}catch{}
      for(const id of ['qualification_and_identity','matched_qualification','native_comment_identity','persisted_comment_readback'])set(id,admitted,source+'leadgen-committed-partial.admittedRows',{ids,identity_and_policy_verified:admitted});
      const stored=rows.map(row=>({id:row.id,run_matches:row.judgment_config?.run_id===run,...require('./leadgen-policy-review.js').verifyStoredScore(row,config.snapshot)}));
      const scores=exact&&stored.every(x=>x.status==='pass'&&x.run_matches);
      set('persisted_scores',scores,source+'leadgen_comments.judgment_config',{stored});
      set('existing_score_readback',scores,source+'leadgen_comments.judgment_config',{stored});
      const once=scores&&rows.every(x=>x.judgment_config?.model_audit?.stage==='single'&&x.judgment_config?.model_audit?.model_call_count===1);
      set('no_duplicate_evaluation',once,source+'leadgen_comments.judgment_config.model_audit',{ids,single_evaluation:once,new_model_calls:0});
      if(activity==='collection') {
        // A partial sample is valid only when the host explicitly requests it; it isn't exhaustion.
        set('honest_coverage',scope.coverage==='committed_partial'&&exact&&ids.length<=c.comment_limit,source+'leadgen_comments',{ids,coverage:scope.coverage,video_exhaustion_claimed:false});
      }
      if(activity==='mark_leads') {
        const related=rows.filter(r=>r.relevance==='相关');
        const outbox=related.length?await query('SELECT * FROM zenithjoy.leadgen_bridge_outbox WHERE line_key=$1 AND comment_id=ANY($2::uuid[])',[c.line,related.map(r=>r.id)]):[];
        const leads=outbox.length?await query('SELECT * FROM zenithjoy.leadgen_leads WHERE line_key=$1 AND id=ANY($2::uuid[])',[c.line,outbox.map(o=>o.lead_id)]):[];
        const bridge=require('./leadgen-outreach-bridge.js');
        const mapped=exact&&related.every(r=>{const matches=outbox.filter(o=>o.comment_id===r.id&&o.payload?.scoring_run===run);return matches.length===1&&leads.filter(l=>l.id===matches[0].lead_id&&l.douyin_id===r.douyin_id).length===1;});
        const persisted=mapped&&outbox.every(o=>bridge.digest(o.payload)===o.payload_sha256)&&rows.every(r=>r.process_status==='已分拣');
        set('lead_identity_and_scope',mapped,source+'leadgen_leads+leadgen_bridge_outbox',{comment_ids:ids,lead_ids:leads.map(l=>l.id)});
        set('persisted_leads',persisted,source+'leadgen_leads+leadgen_bridge_outbox',{lead_ids:leads.map(l=>l.id),outbox_ids:outbox.map(o=>o.id)});
        if(!related.length)set('delivery_readback',exact,source+'leadgen_comments',{no_related_comments:true,external_delivery_required:false});
        if(related.length&&v.verify_crm_delivery===true&&persisted) {
          try {
            const local=await bridge.readbackBridge(client,{line:c.line,run,source_run:null,ids:outbox.map(o=>o.id)});
            const route=require('./line-routes.js').routeOf(c.line);
            // A read-only transport also prevents accidentally invoking a writer exposed by the old client.
            const readOnlyFetch=(url,opts={})=>{
              const method=(opts.method||'GET').toUpperCase();
              if(method!=='GET'&&!(method==='POST'&&url==='https://open.feishu.cn/open-apis/auth/v3/tenant_access_token/internal'))throw Error('READ_ONLY_CRM_METHOD_REQUIRED');
              return fetch(url,opts);
            };
            const api=await require('./leadgen-outreach-orders.js').orderClient(route,{env:{LEADGEN_FEISHU_CREDENTIALS:path.join(os.homedir(),'.credentials/leadgen-feishu-yuesheng-live.json')},fetcher:readOnlyFetch,deadlineAt:Date.now()+30000});
            const reads=[];
            for(const row of outbox) {
              if(row.state==='excluded'&&row.qualification_status==='excluded'){reads.push({outbox_id:row.id,excluded:true,verified:true});continue;}
              if(row.state!=='confirmed'){reads.push({outbox_id:row.id,verified:false,reason:'outbox_not_confirmed'});continue;}
              const record=await api.get(row.feishu_record_id);
              const txt=require('./next-outreach-lib.js').txt;
              const changed_fields=Object.entries(row.fields||{}).filter(([k,value])=>txt(record?.fields?.[k])!==String(value)).map(([k])=>k);
              let matched=record?.record_id===row.feishu_record_id&&bridge.fieldsMatch(row,record), downstream_task=null;
              const follow=v.downstream_tasks?.[row.feishu_record_id];
              if(!matched&&UUID.test(follow||'')) {
                const response=await brainRead('/tasks/'+follow),task=response.task||response;
                matched=task.id===follow&&downstreamDeliveryMatch(row,record,task,c,txt);
                if(matched)downstream_task=follow;
              }
              reads.push({outbox_id:row.id,record_id:record?.record_id,verified:matched,changed_fields,downstream_task});
            }
            set('delivery_readback',local.verified===true&&reads.length===outbox.length&&reads.every(x=>x.verified),
                'feishu:GET/'+route.lead,{reads,local_outbox_verified:local.verified,external_write_calls:0});
          } catch {
            set('delivery_readback',null,'feishu:GET/readback',{reason:'external_delivery_unverified',external_write_calls:0});
          }
        }
        result.output.outbox_states=outbox.map(o=>({id:o.id,state:o.state,feishu_record_id:o.feishu_record_id}));
      }
      result.output.comment_ids=ids;
    }
    await client.query('ROLLBACK');
  } catch(error) {
    // No raw exception messages: DB/HTTP exceptions may contain credentials.
    result.output.readback_error=error.code||(/^[A-Z0-9_]+$/.test(error.message)?error.message:'READBACK_UNAVAILABLE');
  } finally {client?.release();if(pool)await pool.end();}
  result.checks=[...checks.values()];
  result.outcome=result.checks.length>0&&result.checks.every(x=>x.status==='passed')?((result.output.no_collectable_videos===true||result.output.queue_empty===true)?'empty':'passed'):'blocked';
  return result;
}
if(process.argv[1]&&path.resolve(process.argv[1])===path.resolve(new URL(import.meta.url).pathname)) {
  try{const request=JSON.parse(fs.readFileSync(0,'utf8'));console.log(JSON.stringify(await main(request)));}
  catch{console.log(JSON.stringify({error:'READBACK_REQUEST_INVALID'}));process.exitCode=2;}
}

