import {evaluateNative,readNative} from './native-readback.mjs';
import fs from 'node:fs';import path from 'node:path';import {createRequire} from 'node:module';
export function cleanupResult(request,facts,owned){
 const identity=Object.fromEntries(['task_id','run_id','run_tag','workflow','activity','attempt'].map(k=>[k,request[k]]));
 const observed=evaluateNative(facts,request.context,'cleanup');observed.video_leases_released={value:Array.isArray(owned)&&owned.length===0,observation:{owned_video_ids:Array.isArray(owned)?owned.map(x=>x.video_id):'unavailable'}};
 const checks=request.checks.map(id=>({id,status:observed[id]?.value===true?'passed':observed[id]?.value===false?'failed':'unknown',evidence:[{source:id==='video_leases_released'?'postgres:zenithjoy/leadgen_videos':'native+Brain:read-only',observation:observed[id]?.observation??{reason:'unsupported_cleanup_check'}}]}));
 return {identity,nonce:request.nonce,checks,outcome:checks.length===5&&checks.every(x=>x.status==='passed')?'passed':'blocked',output:{read_only:true,model_call_count:0,resources_released:checks.every(x=>x.status==='passed')}};
}
export async function verifyCleanup(request){
 const c=request.context,identity=c.tasks?.[request.workflow];
 if(c.assigned_workflow!==request.workflow||!['task_id','run_id','run_tag'].every(k=>identity?.[k]===request[k]))throw Error('CLEANUP_SCOPE_MISMATCH');
 const facts=await readNative(c,request.run_tag);let owned,pool;
 try{
  const require=createRequire(c.runtime_root+'/package.json'),{Pool}=require('pg');pool=new Pool({connectionString:JSON.parse(fs.readFileSync(path.join(process.env.HOME,'.credentials/zenithjoy-db.json'))).DATABASE_URL,connectionTimeoutMillis:10000,max:1});const client=await pool.connect();
  try{await client.query('BEGIN READ ONLY');await client.query("SET LOCAL statement_timeout='10000ms'");if((await client.query('SELECT current_database() AS db')).rows[0].db!=='zenithjoy')throw Error('WRONG_DB');owned=(await client.query('SELECT video_id FROM zenithjoy.leadgen_videos WHERE line_key=$1 AND process_status=$2',[c.line,'处理中:'+request.run_tag])).rows;await client.query('ROLLBACK');}finally{client.release();}
 }catch{owned=undefined;}finally{if(pool)await pool.end();}
 return cleanupResult(request,facts,owned);
}

