import {createHash} from 'node:crypto';
function errorFacts(error,depth=0){
 const name=typeof error?.name==='string'&&/^(?:[A-Za-z]+Error|Error)$/.test(error.name)?error.name:'UnknownError';
 const value=error?.code,code=typeof value==='number'?value:typeof value==='string'&&/^[A-Z][A-Z0-9_]{0,79}$/.test(value)?value:null;
 return {name,code,...(error?.cause&&depth<2?{cause:errorFacts(error.cause,depth+1)}:{})};
}
function requestId(response){const v=response?.headers?.get?.('x-request-id')||response?.headers?.get?.('x-dashscope-request-id');return typeof v==='string'&&/^[A-Za-z0-9_-]{1,128}$/.test(v)?v:null;}
/** 仅记录可证明阶段；fetch无headers不等于服务端未收到，不重试。 */
export function createAuditedHttp({stage,audit,timeout,fetchImpl=fetch,now=Date.now,makeSignal=AbortSignal.timeout}){
 return async(url,body,key)=>{
  const started=now(),started_at=new Date(started).toISOString();let response,signal,timeout_ms,request_bytes,request_sha256;
  const record=(extra)=>audit({http_status:response?.status??null,body:{},stage,started_at,finished_at:new Date(now()).toISOString(),elapsed_ms:now()-started,provider:stage==='asr'?'dashscope':'openrouter',model:body.model,timeout_ms,request_bytes,request_sha256,request_id:requestId(response),signal_aborted:signal?.aborted===true,provider_received:response?'http_response_received':'unknown',...extra});
  let serialized;
  try{serialized=JSON.stringify(body);request_bytes=Buffer.byteLength(serialized);request_sha256=createHash('sha256').update(serialized).digest('hex');timeout_ms=timeout();signal=makeSignal(timeout_ms);}
  catch(error){record({transport_phase:'not_started',provider_received:'not_sent',transport_error:'REQUEST_NOT_STARTED',error:errorFacts(error)});throw Error('PROVIDER_REQUEST_NOT_STARTED');}
  try{response=await fetchImpl(url,{method:'POST',headers:{Authorization:'Bearer '+key,'Content-Type':'application/json'},body:serialized,signal});}
  catch(error){record({transport_phase:'fetch_awaiting_headers',transport_error:'REQUEST_UNCONFIRMED',error:errorFacts(error)});throw Error('PROVIDER_REQUEST_UNCONFIRMED');}
  let payload;
  try{payload=await response.json();}
  catch(error){record({transport_phase:'response_json_unconfirmed',transport_error:'RESPONSE_BODY_UNCONFIRMED',response_parse_error:true,error:errorFacts(error)});throw Error('PROVIDER_RESPONSE_UNVERIFIED');}
  record({transport_phase:'response_json_received',body:payload});
  if(!response.ok||!payload||typeof payload!=='object'||Array.isArray(payload)||payload.response_parse_error)throw Error('PROVIDER_RESPONSE_UNVERIFIED');
  return payload;
 };
}

