import {spawn} from 'node:child_process';
const broker=String.raw`
import os,sys,fcntl,stat,json
p=sys.argv[1]
fd=os.open(p,os.O_CREAT|os.O_RDWR|os.O_NOFOLLOW,0o600)
s=os.fstat(fd)
if not stat.S_ISREG(s.st_mode) or s.st_uid!=os.getuid() or stat.S_IMODE(s.st_mode)!=0o600:sys.exit(14)
try:fcntl.flock(fd,fcntl.LOCK_EX|fcntl.LOCK_NB)
except BlockingIOError:sys.exit(15)
os.ftruncate(fd,0);os.write(fd,json.dumps({'broker_pid':os.getpid(),'parent_pid':os.getppid()}).encode());os.fsync(fd)
print('READY',flush=True)
sys.stdin.buffer.read()
fcntl.flock(fd,fcntl.LOCK_UN);os.close(fd)
`;
/** 管道由当前helper唯一持有，helper死亡后EOF释放OS锁；不删除锁文件。 */
export async function acquireProcessLock(file){
 const child=spawn('python3',['-c',broker,file],{stdio:['pipe','pipe','pipe']});
 child.stdin.on('error',()=>{});let closed=false;
 const done=new Promise(resolve=>{child.once('error',()=>{closed=true;resolve(-1);});child.once('close',code=>{closed=true;resolve(code);});});
 await new Promise((resolve,reject)=>{
  let text='';child.stdout.on('data',chunk=>{text+=chunk.toString();if(text==='READY\n')resolve();else if(text.length>64)reject(Error('HELPER_LOCK_PROTOCOL'));});
  child.once('error',()=>reject(Error('HELPER_LOCK_UNAVAILABLE')));
  child.once('close',()=>reject(Error('HELPER_LOCK_HELD_OR_UNCONFIRMED')));
 });
 return {assertHeld(){if(closed)throw Error('HELPER_LOCK_LOST');},async release(){child.stdin.end();const code=await done;if(code!==0)throw Error('HELPER_LOCK_RELEASE_UNCONFIRMED');}};
}

