  const identityFile=path.join(work,v.run+'-identity-'+i.video_id+'.json');write(identityFile,{verified:true,content_type:'video',expected_video_id:i.video_id,observed_video_id:i.video_id,evidence_id:i.video_eid,original_receipt:i.video_identity,...(i.video_identity_scratch?{original_scratch:i.video_identity_scratch}:{})});
  const companyFile=path.join(work,v.run+'-company-binding.json');write(companyFile,binding);
  const args={runDir:work,line:c.line,run:v.run,sourceRun:null,videoId:i.video_id,videoUrl:'https://www.douyin.com/video/'+i.video_id,profile:c.profile,douyinId:i.douyin_id,nickname:i.nickname,commentBody:i.comment_body,started:i.started_at_epoch_seconds,profilePath:path.join(native,path.basename(v.profile.file)),returnedPath:path.join(native,path.basename(v.returned.file)),profileEid:i.profile_eid,videoEid:i.video_eid,commentEncoding:'canonical',companyBindingFile:companyFile,companyBindingSha:hash(fs.readFileSync(companyFile))};
  const result=await d.capture(args,evidenceRoot);const out={status:'evidence_built',business_success_claimed:false,video_id:i.video_id,evidence:{path:result.file,sha256:result.sha256},body_sha256:result.body_sha256,company_binding:{path:companyFile,sha256:args.companyBindingSha},video_identity:{path:identityFile,sha256:hash(fs.readFileSync(identityFile))}};write(resultPath,out);return out;
